import java.io.*;import java.nio.file.*;import java.nio.channels.*;import java.util.*;
import vn.rtr.aeris.cockpit03.WorkspaceStore;import vn.rtr.aeris.beta01runtime.*;
public final class StoreQA {
 interface Op{void run()throws Exception;}static File root;static List<Map<String,Object>>results=new ArrayList<>();
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}static void deny(Op o)throws Exception{boolean fail=false;try{o.run();}catch(IOException e){fail=true;}check(fail,"expectedIOException");}static void test(String id,Op o){try{o.run();results.add(Values.map("id",id,"pass",true));}catch(Throwable e){results.add(Values.map("id",id,"pass",false,"error",e.toString()));}}
 static NativeSegments.Sync sync=new NativeSegments.Sync(){public void file(FileDescriptor f)throws IOException{f.sync();}public void directory(File f)throws IOException{try(FileChannel c=FileChannel.open(f.toPath(),StandardOpenOption.READ)){c.force(true);}}};
 static File folder(String id)throws Exception{File f=new File(root,id);check(f.mkdir(),"exclusivefixture");return f;}
 static byte[]b(String s)throws Exception{return s.getBytes("UTF-8");}
 public static void main(String[]args)throws Exception{root=new File(args[0]);check(root.mkdir(),"exclusiveroot");
  test("W01_SAVE_RESTART_STALE_REVISION",()->{File f=folder("basic");WorkspaceStore s=new WorkspaceStore(f,sync);byte[]v=b("{\"draft\":1}");String h=s.saveDraft(0,v);WorkspaceStore restart=new WorkspaceStore(f,sync);check(restart.revision()==1&&Values.hash(WorkspaceStore.read(restart.latestDraft())).equals(h),"restartbytes");deny(()->restart.saveDraft(0,b("{\"draft\":2}")));});
  test("W02_REVIEW_RUN_PREFIX_IS_EXACT",()->{File f=folder("prefix");WorkspaceStore s=new WorkspaceStore(f,sync);byte[]v=b("{\"status\":\"UNKNOWN\"}");String h=s.saveReview("alpha-beta",v);s.saveReview("alpha",v);check(new File(f,"review-alpha-"+h+".json").isFile(),"alpha aliased to alpha-beta withoutownrecord");});
  test("W03_DUPLICATE_REVIEW_RUN_CONFLICT_REJECTED",()->{File f=folder("review-conflict");byte[]a=b("{\"status\":\"UNKNOWN\"}"),z=b("{\"status\":\"FAILED\"}");Files.write(new File(f,"review-run-"+Values.hash(a)+".json").toPath(),a,StandardOpenOption.CREATE_NEW);Files.write(new File(f,"review-run-"+Values.hash(z)+".json").toPath(),z,StandardOpenOption.CREATE_NEW);deny(()->new WorkspaceStore(f,sync));});
  test("W04_POST_RENAME_DIRSYNC_FAILURE_NOT_SILENTLY_PROMOTED",()->{File parent=folder("dirsync");File f=new File(parent,"workspace");boolean[]armed={false};NativeSegments.Sync fault=new NativeSegments.Sync(){public void file(FileDescriptor fd)throws IOException{sync.file(fd);}public void directory(File d)throws IOException{sync.directory(d);File[]finals=f.listFiles((x,n)->n.endsWith(".json"));if(armed[0]&&d.equals(f)&&finals!=null&&finals.length>0)throw new IOException("QA_POST_RENAME_DIR_FSYNC_FAILURE");}};WorkspaceStore s=new WorkspaceStore(f,fault);armed[0]=true;deny(()->s.saveDraft(0,b("{\"draft\":1}")));check(f.listFiles((d,n)->n.endsWith(".json")).length==1,"faultnotafterrename");deny(()->new WorkspaceStore(f,sync));});
  test("W05_SYMLINK_WORKSPACE_ROOT_REFUSED",()->{File parent=folder("symlink");File target=new File(parent,"target");check(target.mkdir(),"target");File link=new File(parent,"workspace");Files.createSymbolicLink(link.toPath(),target.toPath());deny(()->new WorkspaceStore(link,sync));});
  test("W06_PENDING_AND_CORRUPT_SHA_FAIL_LOUD",()->{File f=folder("pending");Files.write(new File(f,"draft-000001.pending").toPath(),b("pending"));deny(()->new WorkspaceStore(f,sync));File z=folder("badsha");Files.write(new File(z,"draft-000001-"+String.join("",Collections.nCopies(64,"0"))+".json").toPath(),b("different"));deny(()->new WorkspaceStore(z,sync));});
  System.out.println(Values.json(Values.map("results",results,"scope","PURE_JVM_REAL_FILESYSTEM_FAULTS_NO_ANDROID_OR_FLIGHT")));
 }
}
